using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
using UnityEngine.Rendering.Universal;
public static class InspectSector {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));
 static string O=>R+"/Docs/검수/2026-11-06_B5_Sector01/";
 static string PathOf(Transform t){return t.parent?PathOf(t.parent)+"/"+t.name:t.name;}
 public static object Read(){var s=SceneManager.GetActiveScene();if(s.isDirty||EditorApplication.isPlaying)throw new Exception("Saved Edit scene required");if(!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception(s.path);Directory.CreateDirectory(O);Directory.CreateDirectory(R+"/SourceAssets/B5_Sector01");if(!File.Exists(R+"/SourceAssets/B5_Sector01/B5_before.unity"))File.Copy(s.path,R+"/SourceAssets/B5_Sector01/B5_before.unity");
 var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular"));
 var things=root.GetComponentsInChildren<Renderer>(true).Where(r=>r.bounds.Intersects(new Bounds(new Vector3(-15,-78,-10),new Vector3(20,10,20)))).Select(r=>new{path=PathOf(r.transform),active=r.gameObject.activeInHierarchy,center=new[]{r.bounds.center.x,r.bounds.center.y,r.bounds.center.z},size=new[]{r.bounds.size.x,r.bounds.size.y,r.bounds.size.z},materials=r.sharedMaterials.Select(m=>m?AssetDatabase.GetAssetPath(m):"MISSING").ToArray()}).ToArray();
 var lights=root.GetComponentsInChildren<Light>(true).Select(l=>new{path=PathOf(l.transform),active=l.enabled,pos=new[]{l.transform.position.x,l.transform.position.y,l.transform.position.z},l.intensity,l.range}).ToArray();
 var props=root.transform.Find("Existing_Props_FirstPass").Cast<Transform>().Select(g=>new{g.name,position=g.position.ToString(),rotation=g.eulerAngles.ToString(),children=g.GetComponentsInChildren<Transform>(true).Select(t=>t.name).ToArray()}).ToArray();
 var obj=new{scene=s.path,things,lights,props,player=s.GetRootGameObjects().Where(g=>g.name.StartsWith("Player")).Select(g=>new{g.name,pos=g.transform.position.ToString(),controllers=g.GetComponentsInChildren<CharacterController>(true).Select(c=>new{c.radius,c.height,center=c.center.ToString(),c.stepOffset}).ToArray()}).ToArray()};File.WriteAllText(O+"before.json",JsonConvert.SerializeObject(obj,Formatting.Indented));return new{renderers=things.Length,lights=lights.Length,props=props.Length};}
 public static object Capture(){var s=SceneManager.GetActiveScene();if(s.isDirty||EditorApplication.isPlaying)throw new Exception("Saved Edit scene required");Directory.CreateDirectory(O);var rr=s.GetRootGameObjects().Where(g=>g.name.StartsWith("Player")).SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).ToArray();var enabled=rr.Select(r=>r.enabled).ToArray();foreach(var r in rr)r.enabled=false;
 var shots=new[]{new{name="before_entry",p=new Vector3(-17.3f,-80.35f,-1.2f),t=new Vector3(-14,-80,-13)},new{name="before_living",p=new Vector3(-9.2f,-80.35f,-10),t=new Vector3(-20,-80.7f,-15)},new{name="before_north",p=new Vector3(-15,-80.35f,-17),t=new Vector3(-16,-80,0)},new{name="before_top",p=new Vector3(-15,-72.5f,-10),t=new Vector3(-15,-82,-10)}};
 try{foreach(var q in shots){var go=new GameObject("SectorReview");var cam=go.AddComponent<Camera>();cam.transform.position=q.p;cam.transform.LookAt(q.t);cam.fieldOfView=75;cam.nearClipPlane=.03f;cam.farClipPlane=200;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.025f,.035f,.045f);cam.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1600,1000,24);cam.targetTexture=rt;cam.Render();var prev=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1000),0,0);tex.Apply();File.WriteAllBytes(O+q.name+".png",tex.EncodeToPNG());RenderTexture.active=prev;cam.targetTexture=null;UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 finally{for(int i=0;i<rr.Length;i++)rr[i].enabled=enabled[i];EditorSceneManager.OpenScene(s.path);}return shots.Length;}
}
